import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"3.1 连接并查看桌面设备","description":"让用户看清设备、权限范围和停止入口。","frontmatter":{"title":"3.1 连接并查看桌面设备","description":"让用户看清设备、权限范围和停止入口。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/3-1.md","filePath":"delivery/stage-3/3-1.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-3/3-1.md"};function o(n,a,s,d,h,_){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="_3-1-连接并查看桌面设备" tabindex="-1">3.1 连接并查看桌面设备 <a class="header-anchor" href="#_3-1-连接并查看桌面设备" aria-label="Permalink to &quot;3.1 连接并查看桌面设备&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 六位配对码、设备令牌、配对审批与能力审批分离；观察、控制、界面自动化逐项授权；应用白名单；在线状态和撤销设备。</li><li><strong>仍未完成：</strong> 托盘或全局常驻的“自动控制中”提示；目前仅支持 Windows 同机助手。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户能把一台电脑安全地连接到 Hearth，并清楚看到这台设备能做什么、当前是否在线、允许操作哪些应用。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>提供简单的桌面助手安装和配对流程，用户在 Hearth 里确认后才建立连接。</li><li>显示设备名称、在线状态、可用的操作范围和最近一次活动时间。</li><li>只允许用户明确选择的应用和窗口，不默认开放整个桌面。</li><li>连接期间始终显示可见提示，用户能随时暂停或断开。</li><li>提供撤销设备入口；撤销后设备不能继续操作或查看任务。</li><li>用真实设备验证：用户能看懂权限范围，也能立即停止连接。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
